    /** Vnitřek <svg> pro danou ikonu, nebo null, když ji neznáme. */
    public static function obsah(string $nazev): ?string
    {
        return self::IKONY[$nazev] ?? null;
    }

    /**
     * Celý element <svg>. Neznámá ikona vrátí prázdný řetězec, ať se rozložení nerozbije.
     * Barvu ikona dědí z textu (stroke="currentColor"), velikost v px.
     */
    public static function svg(string $nazev, int $velikost = 16, string $class = '', ?string $title = null): string
    {
        $obsah = self::obsah($nazev);
        if ($obsah === null) {
            return '';
        }
        $cls = trim('ikona ' . $class);
        $aria = $title !== null
            ? 'role="img" aria-label="' . htmlspecialchars($title, ENT_QUOTES, 'UTF-8') . '"'
            : 'aria-hidden="true"';
        return sprintf(
            '<svg class="%s" width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" %s focusable="false">%s</svg>',
            htmlspecialchars($cls, ENT_QUOTES, 'UTF-8'),
            $velikost,
            $velikost,
            $aria,
            $obsah
        );
    }

    /** Názvy všech dostupných ikon. */
    public static function seznam(): array
    {
        return array_keys(self::IKONY);
    }
}
